INSERT INTO `ajustes` (`id`, `league_name`, `short_name`, `tagline`, `description`, `season`, `season_number`, `modality`, `status`, `status_note`, `server`, `map`, `match_duration`, `tolerance`, `points_win`, `points_draw`, `tiktok`, `tiktok_handle`, `founded`, `match_config`, `donation_note`, `donation_key`, `donation_goal`) VALUES (1, 'The Diamonds League', 'TDL', 'Liga competitiva de HaxBall X5', 'The Diamonds League es la liga competitiva de HaxBall X5 con 2 divisiones, 12 equipos en División 1, salas públicas abiertas y calendario oficial por jornadas.', 'Temporada 3', 3, '5 vs 5', 'ACTIVA', 'Temporada 3 en curso · Inscripciones abiertas', 'X Hosting', '5v5 Diamonds League', 'Dos tiempos de 10:00 + última jugada', '15 minutos', 3, 1, 'https://www.tiktok.com/@diamondsleague89?is_from_webapp=1&sender_device=pc', '@diamondsleague89', '2025', '[{"label":"Modalidad","value":"5 vs 5 · X5"},{"label":"Duración","value":"Dos tiempos de 10:00 + última jugada"},{"label":"Mapa","value":"5v5 Diamonds League"},{"label":"Servidor","value":"X Hosting"}]', 'Tus aportes pagan servidores, premios y material de la liga.', '', 0);
INSERT INTO `divisiones` (`id`, `name`, `code`, `season`, `summary`, `teams`, `journeys`, `playoffs`, `relegation`, `promotion`, `phases`, `movement`, `rules`, `sort_order`) VALUES ('d1', 'División 1', 'D1', 'Temporada 3', 'La categoría principal: 12 equipos, 11 jornadas y playoffs por el título.', 12, 11, 4, '2 descensos directos', 'Sin ascensos', '[{"label":"Fase 1","title":"Liga regular","text":"Todos contra todos durante 11 jornadas. Victoria 3 puntos, empate 1 punto y derrota 0 puntos.","note":"Clasifican a playoffs los puestos 1°, 2°, 3° y 4°."},{"label":"Fase 2","title":"Playoffs","text":"Semifinal 1: 1° vs 4°. Semifinal 2: 2° vs 3°.","note":"Semifinales a un partido. Final de ida y vuelta."}]', '{"title":"Descenso","items":[{"place":"11° lugar","label":"Descenso directo","text":"Baja a División 2 al terminar la liga regular."},{"place":"12° lugar","label":"Descenso directo","text":"Baja a División 2 al terminar la liga regular."}]}', '[{"title":"Tolerancia","text":"15 minutos antes de aplicar W.O."},{"title":"W.O.","text":"Se aplica si un equipo no presenta mínimo 4 jugadores."},{"title":"Respeto","text":"Cero toxicidad durante los partidos y en los canales de la liga."},{"title":"Resultado y replay","text":"Al terminar el partido es obligatorio enviar el resultado y la repetición."}]', 0);
INSERT INTO `divisiones` (`id`, `name`, `code`, `season`, `summary`, `teams`, `journeys`, `playoffs`, `relegation`, `promotion`, `phases`, `movement`, `rules`, `sort_order`) VALUES ('d2', 'División 2', 'D2', 'Temporada 3', '8 equipos, 7 jornadas, playoffs y dos ascensos a División 1.', 8, 7, 4, 'Sin descenso', '2 ascensos', '[{"label":"Liga","title":"Liga regular","text":"Todos contra todos durante 7 jornadas. Victoria 3 puntos, empate 1 punto y derrota 0 puntos.","note":"Clasifican los puestos 1, 2, 3 y 4."},{"label":"Fase final","title":"Playoffs","text":"2° vs 3° y 4° vs 1°. Las semifinales son únicamente de ida.","note":"La final se juega ida y vuelta."}]', '{"title":"Ascensos","items":[{"place":"Primer ascenso","label":"1° lugar de la liga","text":"Ascenso directo a División 1."},{"place":"Segundo ascenso","label":"Ganador de los Playoffs","text":"El campeón de playoffs siempre asciende."}]}', '[{"title":"Tolerancia","text":"15 minutos."},{"title":"W.O.","text":"Se aplica si un equipo no presenta mínimo 4 jugadores."},{"title":"Resultados","text":"Se debe enviar captura y replay."}]', 1);
