INSERT INTO `reglas` (`id`, `title`, `summary`, `sort_order`) VALUES ('discord', 'Discord', 'Normas de convivencia dentro del servidor de la liga.', 0);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Respeto ante todo","text":"Respeta a todos los miembros, staff y admins. Cualquier falta de respeto será sancionada."}', 0);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Prohibido el spam","text":"No enviar mensajes repetitivos, links sin permiso o flood."}', 1);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Cumplir indicaciones del staff","text":"Las decisiones del staff deben respetarse en todo momento."}', 2);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Cero toxicidad","text":"Quedan prohibidos los insultos, racismo, discriminación, acoso o provocaciones."}', 3);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Contenido adecuado","text":"No se permite contenido NSFW, gore o inapropiado."}', 4);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Uso correcto de canales","text":"Habla en los canales correspondientes y evita el desorden."}', 5);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('discord', 'item', '{"title":"Publicidad con autorización","text":"Partners o promociones solo con autorización del staff."}', 6);
INSERT INTO `reglas` (`id`, `title`, `summary`, `sort_order`) VALUES ('comunidad', 'Comunidad', 'La forma en la que nos comportamos dentro y fuera del juego.', 1);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('comunidad', 'item', '{"title":"Buena conducta","text":"Mantén un ambiente sano y competitivo."}', 0);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('comunidad', 'item', '{"title":"Evitar conflictos","text":"Los problemas personales deben resolverse por privado o con staff."}', 1);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('comunidad', 'item', '{"title":"No suplantación","text":"Está prohibido hacerse pasar por otro usuario o staff."}', 2);
INSERT INTO `regla_items` (`rule_id`, `kind`, `text`, `sort_order`) VALUES ('comunidad', 'item', '{"title":"Nombres y perfiles adecuados","text":"No usar nombres ofensivos o provocativos."}', 3);
INSERT INTO `reglas` (`id`, `title`, `summary`, `sort_order`) VALUES ('division', 'División 1', 'Formato de competición, descenso y configuración de partidos.', 2);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `subtitle`, `text`, `list`, `sort_order`) VALUES ('division', 'bloque', 'Formato de competición', 'Liga regular y playoffs', 'Participan 12 equipos y se juega una vuelta de todos contra todos durante 11 jornadas.', '["Victoria: 3 puntos.","Empate: 1 punto.","Derrota: 0 puntos.","Clasifican los puestos 1°, 2°, 3° y 4°.","Semifinales: 1° vs 4° y 2° vs 3°, únicamente de ida.","Final: ida y vuelta."]', 0);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `subtitle`, `text`, `list`, `sort_order`) VALUES ('division', 'bloque', 'Sistema de descenso', 'Dos descensos directos', '', '["11° lugar: desciende directamente a División 2.","12° lugar: desciende directamente a División 2."]', 1);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `subtitle`, `text`, `list`, `sort_order`) VALUES ('division', 'bloque', 'Configuración de partidos', 'Formato oficial X5', '', '["Modalidad: 5v5.","Duración: dos tiempos de 10:00 minutos más última jugada.","Mapa: 5v5 Diamonds League.","Servidor: X Hosting."]', 2);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `subtitle`, `text`, `list`, `sort_order`) VALUES ('division', 'bloque', 'Reglas generales', 'Antes y después del partido', '', '["Tolerancia de 15 minutos.","W.O. si un equipo no presenta mínimo 4 jugadores.","Respeto obligatorio y cero toxicidad.","Es obligatorio enviar resultado y replay."]', 3);
INSERT INTO `reglas` (`id`, `title`, `summary`, `sort_order`) VALUES ('sanciones', 'Sanciones', 'Escala disciplinaria aplicada por el staff de la liga.', 3);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `kicker`, `tone`, `text`, `list`, `sort_order`) VALUES ('sanciones', 'tarjeta', 'Escala general', 'Comunidad', 'info', 'Las sanciones dependerán de la gravedad de la falta.', '["Advertencia o Warn","Silencio o Mute","Expulsión o Kick","Baneo o Ban"]', 0);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `kicker`, `tone`, `text`, `list`, `sort_order`) VALUES ('sanciones', 'tarjeta', 'Amarilla', 'Tarjeta', 'warn', '2 amarillas equivalen a 1 roja.', '["Conductas antideportivas","Pausas incorrectas","Reclamaciones excesivas"]', 1);
INSERT INTO `regla_items` (`rule_id`, `kind`, `title`, `kicker`, `tone`, `text`, `list`, `sort_order`) VALUES ('sanciones', 'tarjeta', 'Roja', 'Tarjeta', 'danger', 'Sanción más posible suspensión.', '["Insultos graves","Falta de respeto","Conducta antideportiva grave"]', 2);
