INSERT INTO `noticias` (`id`, `title`, `category`, `excerpt`, `body`, `date`, `author`, `image`, `pinned`) VALUES ('news-1', 'Nueva página de The Diamonds League', 'Portada', 'En esta página se reunirán los avisos, resultados, entrevistas y contenido de cada jornada.', 'Todo el contenido oficial de la liga vive aquí: calendario por jornadas, salas públicas, reglas, premios y comunicados. El panel de administración permite actualizar cada módulo sin tocar código.', '2026-07-27', 'Staff', '/assets/diamonds-logo.webp', 1);
INSERT INTO `noticias` (`id`, `title`, `category`, `excerpt`, `body`, `date`, `author`, `image`, `pinned`) VALUES ('news-2', 'Resumen de jornada', 'Periódico', 'Resultados, marcadores y resumen de cada jornada.', 'Publicamos el resumen de cada jornada con marcadores, goleadores y la mejor actuación del partido.', '2026-08-03', 'Staff', '', 0);
INSERT INTO `noticias` (`id`, `title`, `category`, `excerpt`, `body`, `date`, `author`, `image`, `pinned`) VALUES ('news-3', 'Entrevistas', 'Comunidad', 'Entrevistas con jugadores, capitanes, staff y personas de la comunidad.', 'Una conversación con los protagonistas de cada fecha: capitanes, jugadores y staff de The Diamonds League.', '2026-08-10', 'Staff', '', 0);
INSERT INTO `anuncios` (`id`, `kind`, `season`, `title`, `kicker`, `date`, `text`, `bullets`, `closing`, `warning`, `day`, `month`, `year`) VALUES ('ann-1', 'awards', 'Temporada 2', 'Premios de la Temporada 2', 'Ceremonia de premios', '2026-03-11', 'Se anuncian los ganadores de las principales categorías y los clubes campeones de cada división.', '["Balón de Oro · Mejor jugador","Bota de Oro · Máximo goleador","Guante de Oro · Mejor portero","Campeones de División 1 y División 2"]', 'Estos fueron los premios entregados al terminar la Temporada 2.', '', 0, 0, 0);
INSERT INTO `anuncios` (`id`, `kind`, `season`, `title`, `kicker`, `date`, `text`, `bullets`, `closing`, `warning`, `day`, `month`, `year`) VALUES ('ann-2', 'registration', 'Temporada 3', 'Inscripciones para la Temporada 3', 'Inscripciones', '2026-07-27', 'Las inscripciones para la Temporada 3 abren el lunes 27 de julio de 2026. Los equipos y jugadores interesados podrán registrarse para participar desde la primera jornada.', '[]', '', 'Cupos limitados. Revisa el servidor y los anuncios para conocer el proceso de registro.', 27, 7, 2026);
